        print(
            f"  [{status}] {path}"
        )

    print(
        "\nSubmission validation: "
        f"{'PASS' if validation['valid'] else 'FAIL'}"
    )

    configuration = manifest[
        "configuration"
    ]

    print("\nConfiguration:")

    for component in (
        "agent",
        "sampling",
        "analyzer",
    ):
        data = configuration[
            component
        ]

        status = (
            "loaded"
            if data["loaded"]
            else "not loaded"
        )

        print(
            f"  {component:<10}: {status}"
        )

        if data["keys"]:
            print(
                f"    keys: {data['keys']}"
            )

        if data["error"]:
            print(
                f"    error: {data['error']}"
            )

    print("\nPrompts:")

    for name, data in configuration[
        "prompts"
    ].items():

        status = (
            "OK"
            if data["exists"]
            else "MISSING"
        )

        print(
            f"  [{status}] "
            f"{name:<10} "
            f"{data['characters']:,} chars | "
            f"{data['lines']:,} lines"
        )

    total_files = len(
